#include <print>
#include <vector>
#include <utility>

void quick_sort(std::vector<int>& v, int lo, int hi) {
    if (lo >= hi) return;
    int pivot = v[(lo + hi) / 2];
    int i = lo, j = hi;
    while (i <= j) {
        while (v[i] < pivot) ++i;
        while (v[j] > pivot) --j;
        if (i <= j) {
            std::swap(v[i++], v[j--]);
            std::print("段 {}..{} swap 后：", lo, hi);
            for (int x : v) std::print("{} ", x);
            std::println("  此刻 i={} j={}", i, j);
        }
    }
    quick_sort(v, lo, j);
    quick_sort(v, i, hi);
}

int main() {
    std::vector<int> v = {5, 2, 8, 1, 9, 3};
    quick_sort(v, 0, static_cast<int>(v.size()) - 1);
    for (int x : v) std::print("{} ", x);
    std::println("");
    return 0;
}

